import json, sys
data = json.loads(json.loads(sys.stdin.read())['result'])['data']['experiments']

# M3: Check GPU usage across all experiments - find spec.gpu_ids
gpu_usage = {}
for k, v in data.items():
    spec = v.get('spec', {})
    if spec and isinstance(spec, dict):
        gpu_ids = spec.get('gpu_ids', [])
        server = spec.get('server', '')
        if gpu_ids:
            gpu_usage[k] = {'gpu_ids': gpu_ids, 'server': server, 'model_name': spec.get('model_name', '')}

for k, v in sorted(gpu_usage.items()):
    if '8b' not in k.lower() and '7b' not in k.lower():
        print(f'{k}: gpu_ids={v[\"gpu_ids\"]}, server={v[\"server\"]}, model={v[\"model_name\"]}')
print()
print('=== 8B/7B experiments ===')
for k, v in sorted(gpu_usage.items()):
    if '8b' in k.lower() or '7b' in k.lower():
        print(f'{k}: gpu_ids={v[\"gpu_ids\"]}, server={v[\"server\"]}, model={v[\"model_name\"]}')
